// Configuration: Allowed user IDs (Hard-coded as .env is not accessible)
const ALLOWED_USER_IDS = [991635368]; // tinel_c

// Extract message data
const payload = msg.payload || {};
let chatId = payload.chatId;
const messageType = payload.type;
let text = (payload.content || '').trim();

// Get user info
const originalMsg = msg.originalMessage || {};
let userId = originalMsg.from ? originalMsg.from.id : null;
const messageId = originalMsg.message_id;

// Handle callback queries
let answerCallback = null;
if (messageType === 'callback_query') {
    text = payload.data || payload.callback_data || payload.content || 
           (originalMsg.data ? originalMsg.data : '') || '';

    if (!chatId) {
        if (originalMsg.message && originalMsg.message.chat) {
            chatId = originalMsg.message.chat.id;
        } else if (originalMsg.chat) {
            chatId = originalMsg.chat.id;
        }
    }

    if (originalMsg.from) {
        userId = originalMsg.from.id;
    }

    const callbackQueryId = payload.callback_query_id || payload.id || 
                            (originalMsg.id ? originalMsg.id.toString() : null) ||
                            (originalMsg.query_id ? originalMsg.query_id.toString() : null);

    if (callbackQueryId) {
        answerCallback = {
            payload: {
                callback_query_id: callbackQueryId,
                text: '',
                show_alert: false
            },
            topic: 'answerCallbackQuery'
        };
    }
}

// Check if it's a valid message
if ((messageType !== 'message' && messageType !== 'callback_query') || !text || !chatId) {
    return [null, answerCallback, null];
}

// Authorization check
if (ALLOWED_USER_IDS.length > 0 && userId && !ALLOWED_USER_IDS.includes(userId)) {
    msg.payload = {
        chatId: chatId,
        type: 'message',
        content: '❌ Unauthorized. You are not allowed to use this bot.'
    };
    msg.topic = 'unauthorized';
    return [msg, answerCallback, null];
}

// Store chat ID for notifications
if (!flow.get('telegram_chat_ids')) {
    flow.set('telegram_chat_ids', []);
}
const chatIds = flow.get('telegram_chat_ids');
if (!chatIds.includes(chatId)) {
    chatIds.push(chatId);
    flow.set('telegram_chat_ids', chatIds);
}

// Parse command
const command = text.split(' ')[0].toLowerCase();
const args = text.split(' ').slice(1);

// Store telegram data in msg
msg.telegram = {
    chatId: chatId,
    userId: userId,
    messageId: messageId,
    command: command,
    args: args,
    originalText: text
};

// Route and return outputs
// Output 1: Local Switch
// Output 2: Answer Callback
// Output 3: Link Out (All authorized commands)

let localMsg = null;
if (command === '/help' || command === '/start') {
    msg.topic = 'help';
    localMsg = msg;
} else if (command === '/commands' || command === '/list') {
    msg.topic = 'commands';
    localMsg = msg;
} else if (msg.topic !== 'unauthorized') {
    msg.topic = 'unknown';
    // Only set as unknown cross-domain if it's NOT a domain-specific command
    const isDomain = command.startsWith('/gate_') || command === '/gate' || 
                    command.startsWith('/sliding_') || 
                    command.startsWith('/secondary_') || 
                    command.startsWith('/garden') || 
                    command.startsWith('/lights_') || 
                    command.startsWith('/pump_') ||
                    command.startsWith('/energy_') ||
                    command.startsWith('/aquarium_') ||
                    command.startsWith('/camera_') ||
                    command === '/boot' || command === '/shutdown' || command === '/stop' ||
                    command === '/force' || command === '/force_shutdown' || 
                    command === '/status' || command === '/state';

    if (!isDomain) {
        localMsg = msg;
    }
}

return [localMsg, answerCallback, msg];
